update prospeccao p
   set mensagem_abertura = nova.mensagem
  from nova
 where p.codigo = nova.codigo
   and p.mensagem_abertura is distinct from nova.mensagem;

-- ---------------------------------------------------------------------
-- A segunda mensagem perde o pedágio.
--
-- Ela começava com "Posso te perguntar uma coisa?". Como PRIMEIRA
-- mensagem aquilo pedia licença antes de tomar o tempo de um estranho.
-- Agora ela vem depois de uma abertura de cem palavras, para alguém que
-- já leu e não respondeu: pedir licença de novo é uma frase inteira
-- gasta para não perguntar nada.
--
-- O `trim` cobre o espaço que sobra, e o `like` garante que só as que
-- realmente têm o pedágio sejam tocadas.
-- ---------------------------------------------------------------------
update prospeccao
   set pergunta_seguinte = initcap(left(btrim(replace(pergunta_seguinte, 'Posso te perguntar uma coisa?', '')), 1))
                           || substr(btrim(replace(pergunta_seguinte, 'Posso te perguntar uma coisa?', '')), 2)
 where pergunta_seguinte like 'Posso te perguntar uma coisa?%';
